saction (receiver_wallet_address, created_at DESC);CREATE INDEX IF NOT EXISTS idx_blockchain_transaction_sender_customer_createdON blockchain.blockchain_transaction (sender_customer_id, created_at DESC);CREATE INDEX IF NOT EXISTS idx_blockchain_transaction_receiver_customer_createdON blockchain.blockchain_transaction (receiver_customer_id, created_at DESC);COMMENT ON INDEX blockchain.idx_blockchain_transaction_transaction_id IS'STEP 26: Supports direct lookup by transaction_id.';COMMENT ON INDEX blockchain.idx_blockchain_transaction_sender_wallet IS'STEP 26: Supports transaction search by sender wallet address.';COMMENT ON INDEX blockchain.idx_blockchain_transaction_receiver_wallet IS'STEP 26: Supports transaction search by receiver wallet address.';COMMENT ON INDEX blockchain.idx_blockchain_transaction_created_at IS'STEP 26: Supports date range filtering and sorting by created_at.';COMMENT ON INDEX blockchain.idx_blockchain_transaction_type_status_created IS'STEP 26: Supports combined filtering by transaction type, status, and transaction date.';COMMIT;
