7. Chaincode Functions Required for CouchDB Rich Query Option
Your API service expects these Fabric functions:
QueryTransactions(queryString)GetTransactionById(transactionId)
Add these functions inside your JavaScript chaincode contract file.
Example:
async QueryTransactions(ctx, queryString) {  const iterator = await ctx.stub.getQueryResult(queryString);  const results = [];  while (true) {    const res = await iterator.next();    if (res.value && res.value.value.toString()) {      const record = JSON.parse(res.value.value.toString("utf8"));      results.push({        key: res.value.key,        ...record,      });    }    if (res.done) {      await iterator.close();      break;    }  }  return JSON.stringify(results);}async GetTransactionById(ctx, transactionId) {  if (!transactionId) {    throw new Error("transactionId is required");  }  const query = {    selector: {      docType: "TRANSACTION",      transactionId,    },    limit: 1,  };  const iterator = await ctx.stub.getQueryResult(JSON.stringify(query));  const res = await iterator.next();  if (!res.value || !res.value.value.toString()) {    await iterator.close();    throw new Error(`Transaction not found for transactionId: ${transactionId}`);  }  const transaction = JSON.parse(res.value.value.toString("utf8"));  await iterator.close();  return JSON.stringify(transaction);}

8. API Usage Examples
8.1 Get All Transactions from PostgreSQL
curl -X GET "http://127.0.0.1:3001/api/v1/transactions" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_ALL_001"

8.2 Search by Wallet Address
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?walletAddress=WALLET_PENDING_REQ_AEE7B53C59079B041CD63472" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_WALLET_001"

8.3 Search by Customer ID
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?customerId=CUST2017" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_CUSTOMER_001"

8.4 Search by Organization ID
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?organizationId=26af0fd4-80c4-4da6-9240-b66ff88a7023" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_ORG_001"

8.5 Search by Type and Status
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?transactionType=WALLET_TRANSFER&status=COMPLETED" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_TYPE_STATUS_001"

8.6 Search by Date Range
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?dateFrom=2026-05-01T00:00:00Z&dateTo=2026-05-05T23:59:59Z" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_DATE_001"

8.7 Search by Amount Range
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?amountMin=10&amountMax=500" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_AMOUNT_001"

8.8 Pagination and Sorting
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?page=1&limit=10&sortBy=createdAt&sortOrder=desc" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_PAGING_001"

8.9 Get Transaction by ID
Replace the transaction ID with one from your previous successful transfer.
curl -X GET "http://127.0.0.1:3001/api/v1/transactions/d7bbbbca-e75c-4c1a-bb4a-cbf0b6dd8292" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_GET_BY_ID_001"

8.10 Query from Fabric / CouchDB Rich Query
curl -X GET "http://127.0.0.1:3001/api/v1/transactions?source=fabric&transactionType=WALLET_TRANSFER&status=COMPLETED" \-H "Content-Type: application/json" \-H "x-request-id: REQ_TX_HISTORY_FABRIC_001"

